function numKLenSubstrNoRepeats(s, k) {
  const count = new Array(26).fill(0);
  let distinct = 0;
  let answer = 0;

  for (let right = 0; right < s.length; right++) {
    const added = s.charCodeAt(right) - 97;
    if (count[added] === 0) {
      distinct++;
    }
    count[added]++;

    const left = right - k;
    if (left >= 0) {
      const removed = s.charCodeAt(left) - 97;
      count[removed]--;
      if (count[removed] === 0) {
        distinct--;
      }
    }

    if (distinct === k) {
      answer++;
    }
  }
  return answer;
}

