function numKLenSubstrNoRepeats(s, k) {
  let total = 0;
  for (let start = 0; start + k <= s.length; start++) {
    const piece = s.slice(start, start + k);
    if (new Set(piece.split('')).size === piece.length) total++;
  }
  return total;
}

