function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pick = (n) => Math.floor(rand() * n);
  if (size === 'large') {
    const n = 5000 + pick(5001);
    const alphabet = 10 + pick(17);
    const s = Array.from({ length: n }, () => letters[pick(alphabet)]).join('');
    const roll = rand();
    const k = roll < 0.1 ? 1 + pick(10000) : 1 + pick(Math.min(alphabet, 12));
    return [s, k];
  }
  const n = 1 + pick(12);
  const alphabet = 1 + pick(rand() < 0.5 ? 4 : 26);
  const s = Array.from({ length: n }, () => letters[pick(alphabet)]).join('');
  const k = 1 + pick(n + 2);
  return [s, k];
}
